&lt;p data-start=&quot;101&quot; data-end=&quot;215&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;We’re hiring for:&lt;/span&gt;&lt;br data-start=&quot;152&quot; data-end=&quot;155&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong data-start=&quot;155&quot; data-end=&quot;215&quot;&gt;Seasonal &amp;amp; Permanent Fulfillment Associates&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
